import { Inject, Injectable, PLATFORM_ID, TransferState, makeStateKey } from '@angular/core';
import { isPlatformBrowser, isPlatformServer } from '@angular/common';
import { HttpClient } from '@angular/common/http';
import { Observable, of } from 'rxjs';
import { catchError, map, tap } from 'rxjs/operators';
import { environment } from '../../../environments/environment';

export interface PrivacyPolicyContent {
	title: string;
	content: string;
}

interface PrivacyPolicyApiResponse {
	code?: number;
	result?: { title?: string; content?: string } | null;
}

@Injectable({
	providedIn: 'root'
})
export class PrivacyPolicyService {
	private readonly endpoint = `${environment.baseUrl}/api/policies/privacy/current`;

	constructor(
		private readonly http: HttpClient,
		private readonly transferState: TransferState,
		@Inject(PLATFORM_ID) private readonly platformId: Object
	) { }

	// Same TransferState-cache + catchError(() => of(null)) pattern as
	// PageSeoService — a null result means "API unavailable or no active
	// record yet," and the caller falls back to the static template.
	getPrivacyPolicy(locale: 'en' | 'ar'): Observable<PrivacyPolicyContent | null> {
		const stateKey = makeStateKey<PrivacyPolicyContent | null>(`privacy-policy:${locale}`);

		if (isPlatformBrowser(this.platformId) && this.transferState.hasKey(stateKey)) {
			const cached = this.transferState.get<PrivacyPolicyContent | null>(stateKey, null);
			this.transferState.remove(stateKey);
			return of(cached);
		}

		return this.http.get<PrivacyPolicyApiResponse>(this.endpoint, { params: { locale } }).pipe(
			map((response) => this.mapResponse(response)),
			tap((policy) => {
				if (isPlatformServer(this.platformId)) {
					this.transferState.set(stateKey, policy);
				}
			}),
			catchError((error) => {
				console.warn(`PrivacyPolicyService: failed to load Privacy Policy for "${locale}"`, error?.error?.message ?? error?.message);
				return of(null);
			})
		);
	}

	private mapResponse(response: PrivacyPolicyApiResponse): PrivacyPolicyContent | null {
		const policy = response?.result;
		if (!policy || !policy.content) {
			return null;
		}
		return { title: policy.title || '', content: policy.content };
	}
}
